<?php
session_start();require_once '../shared/config.php';requireLogin('customer','login.php');$db=getDB();$customerId=(int)$_SESSION['customer_id'];
$st=$db->prepare("SELECT COALESCE(SUM(CASE WHEN transaction_type='earn' THEN points WHEN transaction_type='redeem' THEN -points ELSE points END),0) FROM rewards WHERE customer_id=?");$st->execute([$customerId]);$points=(int)$st->fetchColumn();
$st=$db->prepare("SELECT COUNT(*) FROM orders WHERE customer_id=? AND status='completed'");$st->execute([$customerId]);$rentals=(int)$st->fetchColumn();
$st=$db->prepare("SELECT COUNT(*) FROM swap_requests sr JOIN swap_listings sl ON sl.id=sr.offered_swap_listing_id WHERE sr.requester_id=? AND sr.status='accepted'");$st->execute([$customerId]);$swaps=(int)$st->fetchColumn();
$history=$db->prepare("SELECT * FROM rewards WHERE customer_id=? ORDER BY created_at DESC LIMIT 30");$history->execute([$customerId]);$history=$history->fetchAll();
?><!doctype html><html><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>O2O Rewards & Circular Fashion</title><style>
body{font-family:Arial;background:#F4F7F4;color:#1A2E1A;margin:0}.nav{background:#0F1B2D;color:#C9A84C;padding:18px 28px}.nav a{color:#E8CC82;text-decoration:none;margin-left:18px}.main{max-width:900px;margin:auto;padding:30px}.hero,.card{background:#fff;padding:22px;margin-bottom:18px;box-shadow:0 2px 10px #0001}.hero{background:#21170B;color:#fff}.stats{display:grid;grid-template-columns:repeat(3,1fr);gap:14px}.stat{background:#fff;padding:20px}.stat b{font-size:30px;display:block;color:#8B1A1A}.row{padding:12px 0;border-bottom:1px solid #eee}.small{font-size:12px;color:#777;line-height:1.6}@media(max-width:650px){.stats{grid-template-columns:1fr}}</style></head><body><div class="nav"><b>O2O Tradition</b><a href="home.php">Home</a><a href="notifications.php">Alerts</a></div><main class="main"><section class="hero"><h1>♻️ Circular Fashion & Rewards</h1><p>O2O Tradition tracks reuse-oriented activity such as completed rentals and swap activity, alongside your reward points.</p></section><div class="stats"><div class="stat">🏆<b><?=$points?></b><small>Reward points</small></div><div class="stat">♻️<b><?=$rentals?></b><small>Completed rentals</small></div><div class="stat">🔄<b><?=$swaps?></b><small>Accepted swap activity</small></div></div><section class="card"><h2>How points work</h2><p class="small">The rewards ledger supports earned, redeemed and adjusted points. Points are only shown when an actual ledger entry exists; this page does not invent environmental savings or assign unverified carbon credits.</p></section><section class="card"><h2>Reward history</h2><?php if(!$history):?><p class="small">No reward transactions yet. Your points history will appear here when rewards are issued.</p><?php else:foreach($history as $h):?><div class="row"><b><?=htmlspecialchars($h['transaction_type']==='earn'?'+':'-')?><?=intval($h['points'])?> points</b> · <?=htmlspecialchars($h['reason'])?><div class="small"><?=date('d M Y, h:i A',strtotime($h['created_at']))?></div></div><?php endforeach;endif;?></section><section class="card"><h2>Reuse activity</h2><p class="small">Completed rentals and community swaps are part of the circular marketplace record. Future versions can add verified reuse metrics and reward rules without claiming environmental impact that has not been measured.</p></section></main></body></html>